<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>MIFECO Consulting Dashboard — TestCorp Upgrade & Pipeline</title>
  <style>
    :root {
      --bg-primary: #0f172a;
      --bg-secondary: #1e293b;
      --bg-card: #1a2332;
      --accent: #00ffcc;
      --accent2: #667eea;
      --accent3: #764ba2;
      --text-primary: #e2e8f0;
      --text-secondary: #94a3b8;
      --border: #334155;
      --success: #22c55e;
      --warning: #f59e0b;
      --danger: #ef4444;
    }
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
      background: var(--bg-primary);
      color: var(--text-primary);
      line-height: 1.6;
    }
    .container { max-width: 1400px; margin: 0 auto; padding: 20px; }
    .header {
      background: linear-gradient(135deg, var(--accent2), var(--accent3));
      padding: 40px;
      border-radius: 16px;
      margin-bottom: 24px;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }
    .header h1 { font-size: 28px; color: white; font-weight: 700; }
    .header p { color: rgba(255,255,255,0.85); font-size: 14px; margin-top: 4px; }
    .header .badge {
      background: rgba(255,255,255,0.2);
      padding: 8px 16px;
      border-radius: 20px;
      font-size: 13px;
      color: white;
    }
    .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-bottom: 20px; }
    .card {
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 24px;
    }
    .card h2 {
      color: var(--accent);
      font-size: 18px;
      margin-bottom: 16px;
      padding-bottom: 8px;
      border-bottom: 1px solid var(--border);
    }
    .full-width { grid-column: 1 / -1; }
    .stat-row { display: flex; gap: 20px; margin-top: 12px; }
    .stat {
      flex: 1;
      background: var(--bg-secondary);
      border-radius: 8px;
      padding: 16px;
      text-align: center;
    }
    .stat .number { font-size: 28px; font-weight: 700; color: var(--accent); }
    .stat .label { font-size: 12px; color: var(--text-secondary); margin-top: 4px; }
    .email-preview {
      background: #1a1a2e;
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 32px;
      font-size: 14px;
      line-height: 1.8;
      white-space: pre-wrap;
      max-height: 600px;
      overflow-y: auto;
    }
    .email-preview .subject {
      color: var(--accent);
      font-size: 16px;
      font-weight: 700;
      margin-bottom: 16px;
      padding: 12px;
      background: var(--bg-secondary);
      border-radius: 8px;
      border-left: 3px solid var(--accent2);
    }
    .tag {
      display: inline-block;
      padding: 2px 8px;
      border-radius: 4px;
      font-size: 11px;
      font-weight: 600;
    }
    .tag-high { background: #fef3c7; color: #92400e; }
    .tag-mid { background: #dbeafe; color: #1e40af; }
    .tag-done { background: #dcfce7; color: #166534; }
    .media-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 12px; }
    .media-item {
      background: var(--bg-secondary);
      border-radius: 8px;
      padding: 12px;
      text-align: center;
      border: 1px solid var(--border);
    }
    .media-item img { max-width: 100%; border-radius: 4px; margin-bottom: 8px; }
    .media-item .filepath { font-size: 10px; color: var(--text-secondary); word-break: break-all; }
    .pipeline-card {
      background: var(--bg-secondary);
      border-radius: 8px;
      padding: 16px;
      margin-bottom: 12px;
      border-left: 3px solid var(--accent2);
    }
    .pipeline-card h3 { color: var(--text-primary); font-size: 14px; }
    .pipeline-card .meta { font-size: 12px; color: var(--text-secondary); margin-top: 4px; }
    .social-preview {
      background: var(--bg-secondary);
      border-radius: 8px;
      padding: 16px;
      margin-bottom: 12px;
    }
    .social-preview .platform { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; }
    .social-preview .platform.linkedin { color: #0a66c2; }
    .social-preview .platform.twitter { color: #1da1f2; }
    .social-preview .body { margin-top: 8px; font-size: 13px; line-height: 1.6; }
    .social-preview .infographic-link { margin-top: 8px; display: inline-block; }
    .checklist { list-style: none; padding: 0; }
    .checklist li {
      padding: 8px 12px;
      margin-bottom: 4px;
      border-radius: 6px;
      font-size: 13px;
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .checklist li.done { background: rgba(34,197,94,0.1); color: var(--success); }
    .checklist li.pending { background: rgba(245,158,11,0.1); color: var(--warning); }
    .checklist li .icon { font-size: 16px; }
    @media (max-width: 768px) {
      .grid { grid-template-columns: 1fr; }
      .header { flex-direction: column; gap: 12px; text-align: center; }
      .stat-row { flex-direction: column; }
    }
    .btn {
      display: inline-block;
      padding: 8px 20px;
      border-radius: 8px;
      font-size: 13px;
      font-weight: 600;
      text-decoration: none;
      cursor: pointer;
    }
    .btn-primary { background: var(--accent); color: #0f172a; }
    .btn-secondary { background: var(--bg-secondary); color: var(--text-primary); border: 1px solid var(--border); }
  </style>
</head>
